"use client";
import type { useRender } from "@base-ui/react/use-render";
import { cva } from "class-variance-authority";
import type { VariantProps } from "class-variance-authority";

import { RenderSpan } from "@/components/ui/render-element";
import type { IconComponent } from "@/lib/icon-context";
import { useShape } from "@/lib/shape-context";
import { useSizeVariant } from "@/lib/size-context";
import { cn } from "@/lib/utils";

export const badgeColors = {
  amber: "#f59e0b",
  blue: "#3b82f6",
  cyan: "#06b6d4",
  emerald: "#10b981",
  fuchsia: "#d946ef",
  gray: "#a3a3a3",
  green: "#22c55e",
  indigo: "#6366f1",
  lime: "#84cc16",
  orange: "#f97316",
  pink: "#ec4899",
  purple: "#a855f7",
  red: "#ef4444",
  rose: "#f43f5e",
  teal: "#14b8a6",
  violet: "#8b5cf6",
  yellow: "#eab308",
} as const;
export type BadgeColor = keyof typeof badgeColors;

const badgeVariants = cva(
  "inline-flex items-center justify-center rounded-md border px-2 py-0.5 text-xs font-medium w-fit whitespace-nowrap shrink-0 [&>svg]:size-3 gap-1 [&>svg]:pointer-events-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive transition-[color,box-shadow] overflow-hidden",
  {
    defaultVariants: {
      variant: "default",
    },
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground [a&]:hover:bg-primary/90",
        destructive:
          "border-transparent bg-destructive text-white [a&]:hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        dot: "border-border text-foreground bg-transparent",
        outline:
          "text-foreground [a&]:hover:bg-accent [a&]:hover:text-accent-foreground",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground [a&]:hover:bg-secondary/90",
        solid: "border-transparent text-foreground",
      },
    },
  }
);

const Badge = ({
  className,
  variant,
  render,
  size,
  color = "gray",
  icon: BadgeIcon,
  children,
  style,
  ...props
}: React.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    render?: useRender.RenderProp;
    size?: "default" | "compact";
    color?: BadgeColor;
    icon?: IconComponent;
  }) => {
  const Comp = RenderSpan;
  const compact = useSizeVariant(size) === "compact";
  const shape = useShape();
  const appearance = variant ?? "solid";
  const tint = badgeColors[color];

  return (
    <Comp
      render={render}
      data-slot="badge"
      data-variant={variant}
      className={cn(
        badgeVariants({ variant: appearance }),
        compact ? "h-5 px-2 text-[11px] gap-1" : "h-6 px-2.5 text-xs gap-1.5",
        shape,
        className
      )}
      style={{
        backgroundColor:
          appearance === "solid"
            ? `color-mix(in srgb, ${tint} 15%, var(--background))`
            : undefined,
        ...style,
      }}
      {...props}
    >
      {appearance === "dot" && (
        <span
          aria-hidden="true"
          className="shrink-0 rounded-full"
          style={{
            backgroundColor: tint,
            height: compact ? 6 : 7,
            width: compact ? 6 : 7,
          }}
        />
      )}
      {BadgeIcon && <BadgeIcon aria-hidden="true" />}
      {children}
    </Comp>
  );
};

export { Badge, badgeVariants };

"use client";

import { useRender } from "@base-ui/react/use-render";

export const RenderDiv = ({
  render,
  ...props
}: useRender.ComponentProps<"div">) =>
  useRender({ defaultTagName: "div", props, render });
export const RenderSpan = ({
  render,
  ...props
}: useRender.ComponentProps<"span">) =>
  useRender({ defaultTagName: "span", props, render });
export const RenderAnchor = ({
  render,
  ...props
}: useRender.ComponentProps<"a">) =>
  useRender({ defaultTagName: "a", props, render });

"use client";

import {
  Check,
  ChevronDown,
  ChevronRight,
  Copy,
  LoaderCircle,
  Search,
  X,
} from "lucide-react";
import { createContext, useContext, useMemo } from "react";
import type { ComponentType, ReactNode, SVGProps } from "react";

export type IconProps = SVGProps<SVGSVGElement> & {
  size?: number;
  strokeWidth?: number;
};
export type IconComponent = ComponentType<IconProps>;
export const defaultIcons = {
  check: Check,
  "chevron-down": ChevronDown,
  "chevron-right": ChevronRight,
  close: X,
  copy: Copy,
  loading: LoaderCircle,
  search: Search,
} satisfies Record<string, IconComponent>;
export type IconName = keyof typeof defaultIcons;
const IconContext =
  createContext<Record<IconName, IconComponent>>(defaultIcons);
export const IconProvider = ({
  icons,
  children,
}: {
  icons: Partial<Record<IconName, IconComponent>>;
  children: ReactNode;
}) => {
  const parent = useContext(IconContext);
  const value = useMemo(() => ({ ...parent, ...icons }), [parent, icons]);
  return <IconContext.Provider value={value}>{children}</IconContext.Provider>;
};
export const Icon = ({ name, ...props }: IconProps & { name: IconName }) => {
  const Component = useContext(IconContext)[name];
  return <Component aria-hidden="true" focusable="false" {...props} />;
};

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type ShapeVariant = "rounded" | "pill";
const ShapeContext = createContext<ShapeVariant>("rounded");
export const shapeMap = {
  pill: "rounded-[20px]",
  rounded: "rounded-lg",
} as const;
export const ShapeProvider = ({
  shape,
  children,
}: {
  shape: ShapeVariant;
  children: ReactNode;
}) => <ShapeContext.Provider value={shape}>{children}</ShapeContext.Provider>;
export const useShape = (override?: ShapeVariant) => {
  const inherited = useContext(ShapeContext);
  return shapeMap[override ?? inherited];
};

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type SizeVariant = "default" | "compact";
const SizeContext = createContext<SizeVariant>("default");
export const sizeMap = {
  compact: {
    control: "h-7",
    controlHeight: 28,
    gap: "gap-1",
    icon: 14,
    iconClass: "[&_svg:not([class*='size-'])]:size-3.5",
    px: "px-2.5",
    text: "text-xs",
    variant: "compact",
  },
  default: {
    control: "h-9",
    controlHeight: 36,
    gap: "gap-2",
    icon: 16,
    iconClass: "[&_svg:not([class*='size-'])]:size-4",
    px: "px-3",
    text: "text-[13px]",
    variant: "default",
  },
} as const;
export const SizeProvider = ({
  size,
  children,
}: {
  size: SizeVariant;
  children: ReactNode;
}) => <SizeContext.Provider value={size}>{children}</SizeContext.Provider>;
export const useSizeVariant = (override?: SizeVariant) => {
  const inherited = useContext(SizeContext);
  return override ?? inherited;
};
export const useSize = (override?: SizeVariant) =>
  sizeMap[useSizeVariant(override)];
